(function() {
  'use strict';

  const api = window.CardSpoke.utils;

  CardSpoke_MODS.register('neon-cyberpunk-theme', {
    meta: {
      name: 'Neon Cyberpunk Theme',
      type: 'Theme',
      version: '1.0.0',
      creator: 'CardSpoke',
      description: 'Futuristic cyberpunk theme with neon accents, glitch effects, and animations'
    },

    glitchInterval: null,

    onAppInit(ctx) {
      ctx.logger.log('Neon Cyberpunk theme initialized');
      this.addScanlineEffect();
      this.startGlitchEffect();
    },

    addScanlineEffect() {
      const scanline = document.createElement('div');
      scanline.className = 'cyberpunk-scanline';
      document.body.appendChild(scanline);
    },

    startGlitchEffect() {
      // Random glitch effect on page title
      this.glitchInterval = setInterval(() => {
        const title = document.querySelector('h1, .app-title');
        if (title && Math.random() > 0.95) {
          title.classList.add('glitch');
          setTimeout(() => title.classList.remove('glitch'), 200);
        }
      }, 3000);
    },

    onCardRender(ctx, card, element) {
      // Add neon glow to urgent cards
      if (card.tags && card.tags.some(tag => tag.toLowerCase().includes('urgent'))) {
        element.classList.add('neon-urgent');
      }
    },

    onDisable(ctx) {
      if (this.glitchInterval) {
        clearInterval(this.glitchInterval);
      }
      const scanline = document.querySelector('.cyberpunk-scanline');
      if (scanline) scanline.remove();
    }
  });
})();

