:root {
  /* Neon Cyberpunk Theme - Dark base with neon accents */
  --bg-primary: #0a0e17;
  --bg-alt: #141824;
  --bg-hover: #1e2433;
  --text-primary: #00ffff;
  --text-secondary: #ff00ff;
  --border: #00ffff;
  --accent: #ff00ff;
  --accent-hover: #ff33ff;
  --neon-cyan: #00ffff;
  --neon-magenta: #ff00ff;
  --neon-yellow: #ffff00;
}

body {
  background: linear-gradient(180deg, #0a0e17 0%, #1a0a2e 100%);
  font-family: 'Courier New', monospace;
}

/* Glowing neon borders */
.card {
  background: rgba(20, 24, 36, 0.9);
  border: 2px solid var(--neon-cyan);
  box-shadow: 
    0 0 10px var(--neon-cyan),
    inset 0 0 10px rgba(0, 255, 255, 0.1);
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(0, 255, 255, 0.2),
    transparent
  );
  transition: left 0.5s;
}

.card:hover::before {
  left: 100%;
}

.card:hover {
  border-color: var(--neon-magenta);
  box-shadow: 
    0 0 20px var(--neon-magenta),
    0 0 30px rgba(255, 0, 255, 0.5),
    inset 0 0 20px rgba(255, 0, 255, 0.1);
}

/* Neon text glow */
.card-title {
  color: var(--neon-cyan);
  text-shadow: 
    0 0 5px var(--neon-cyan),
    0 0 10px var(--neon-cyan);
  font-weight: bold;
  letter-spacing: 1px;
}

/* Button styling */
button, .btn {
  background: transparent;
  border: 2px solid var(--neon-magenta);
  color: var(--neon-magenta);
  text-shadow: 0 0 5px var(--neon-magenta);
  box-shadow: 0 0 10px rgba(255, 0, 255, 0.3);
  transition: all 0.3s;
}

button:hover, .btn:hover {
  background: rgba(255, 0, 255, 0.2);
  box-shadow: 
    0 0 20px var(--neon-magenta),
    0 0 30px rgba(255, 0, 255, 0.5);
  transform: translateY(-2px);
}

/* Tag styling */
.tag {
  background: rgba(255, 255, 0, 0.1);
  border: 1px solid var(--neon-yellow);
  color: var(--neon-yellow);
  text-shadow: 0 0 3px var(--neon-yellow);
  box-shadow: 0 0 5px rgba(255, 255, 0, 0.3);
}

/* Scanline effect overlay */
.cyberpunk-scanline {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 255, 255, 0.03) 0px,
    transparent 1px,
    transparent 2px,
    rgba(0, 255, 255, 0.03) 3px
  );
  z-index: 9999;
  animation: scanline 10s linear infinite;
}

@keyframes scanline {
  0% { transform: translateY(0); }
  100% { transform: translateY(10px); }
}

/* Glitch effect */
@keyframes glitch {
  0% { transform: translate(0); }
  20% { transform: translate(-2px, 2px); }
  40% { transform: translate(-2px, -2px); }
  60% { transform: translate(2px, 2px); }
  80% { transform: translate(2px, -2px); }
  100% { transform: translate(0); }
}

.glitch {
  animation: glitch 0.2s infinite;
}

/* Neon urgent cards */
.neon-urgent {
  border-color: #ff0000 !important;
  box-shadow: 
    0 0 20px #ff0000,
    0 0 30px rgba(255, 0, 0, 0.5),
    inset 0 0 20px rgba(255, 0, 0, 0.1) !important;
  animation: pulse-red 2s infinite;
}

@keyframes pulse-red {
  0%, 100% { box-shadow: 0 0 20px #ff0000, 0 0 30px rgba(255, 0, 0, 0.5); }
  50% { box-shadow: 0 0 30px #ff0000, 0 0 50px rgba(255, 0, 0, 0.7); }
}

/* Scrollbar styling */
::-webkit-scrollbar {
  width: 10px;
  background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
  background: var(--neon-cyan);
  box-shadow: 0 0 10px var(--neon-cyan);
}

::-webkit-scrollbar-thumb:hover {
  background: var(--neon-magenta);
  box-shadow: 0 0 10px var(--neon-magenta);
}
